import type { FC } from 'react';
import { Audio, staticFile } from 'remotion';

// Two stems generated by scripts/score.py. The BGM can be muted with the
// `bgm` prop so the no-BGM delivery keeps the designed SFX.
export const Soundtrack: FC<{ bgm: boolean }> = ({ bgm }) => (
  <>
    {bgm ? <Audio src={staticFile('audio/bgm/apple-score-bgm.wav')} /> : null}
    <Audio src={staticFile('audio/sfx/apple-score-sfx.wav')} />
  </>
);
